public void init()
{
    next init();

    if (METSecurityPolicyHelper::isRoleActiveForCurrentUser(roleStr(METInventLocationPolicyRole))
        && !Global::isSystemAdministrator())
    {
        container warehouseCon = METUserSecurityWarehouseList::findMultipleWarehouseByUser();

        this.applyWarehouseFilter(warehouseCon);
        InventTransferJour_DS.executeQuery();
    }
}

private void applyWarehouseFilter(container _warehouseCon)
{
    QueryBuildDataSource qbds;
    QueryBuildRange      qbr;
    InventLocationId     warehouseId;
    str                  rangeValue;
    int                  i;

    qbds = InventTransferJour_DS.query().dataSourceTable(tableNum(InventTransferJour));

    qbr = SysQuery::findOrCreateRange(qbds,
        fieldNum(InventTransferJour, RecId));

    // If no warehouses → block all data
    if (!conLen(_warehouseCon))
    {
        qbr.value('0');
        return;
    }

    for (i = 1; i <= conLen(_warehouseCon); i++)
    {
        warehouseId = conPeek(_warehouseCon, i);

        if (warehouseId)
        {
            if (rangeValue)
            {
                rangeValue += ' || ';
            }

            rangeValue += strFmt(
                '((%1 == "%2") || (%3 == "%2"))',
                fieldStr(InventTransferJour, InventLocationIdFrom),
                warehouseId,
                fieldStr(InventTransferJour, InventLocationIdTo));
        }
    }

    if (rangeValue)
    {
        qbr.value(strFmt('(%1)', rangeValue));
    }
}
